window.ScripturaLexicons.BDAG_PART_0251 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-01\" data-source=\"BDAG\" data-search=\"οἰκητήριον, ου, τό substantivo neutro morada; habitação; lugar de residência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκητήριον, ου, τό</td><td>substantivo neutro</td><td>morada; habitação; lugar de residência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-02\" data-source=\"BDAG\" data-search=\"οἰκήτωρ, ορος, ὁ substantivo masculino habitante; morador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκήτωρ, ορος, ὁ</td><td>substantivo masculino</td><td>habitante; morador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-03\" data-source=\"BDAG\" data-search=\"οἰκία, ας, ἡ substantivo feminino casa; edifício; família; conjunto doméstico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκία, ας, ἡ</td><td>substantivo feminino</td><td>casa; edifício; família; conjunto doméstico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-04\" data-source=\"BDAG\" data-search=\"οἰκιακός, οῦ, ὁ substantivo masculino membro da casa; familiar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκιακός, οῦ, ὁ</td><td>substantivo masculino</td><td>membro da casa; familiar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-05\" data-source=\"BDAG\" data-search=\"οἰκοδεσποτέω verbo administrar a casa; governar o lar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδεσποτέω</td><td>verbo</td><td>administrar a casa; governar o lar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-06\" data-source=\"BDAG\" data-search=\"οἰκοδεσπότης, ου, ὁ substantivo masculino senhor da casa; dono; chefe de família BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδεσπότης, ου, ὁ</td><td>substantivo masculino</td><td>senhor da casa; dono; chefe de família</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-07\" data-source=\"BDAG\" data-search=\"οἰκοδομέω verbo construir; reconstruir; edificar; fortalecer BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδομέω</td><td>verbo</td><td>construir; reconstruir; edificar; fortalecer</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-08\" data-source=\"BDAG\" data-search=\"οἰκοδομή, ῆς, ἡ substantivo feminino construção; edificação; edifício; fortalecimento espiritual BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδομή, ῆς, ἡ</td><td>substantivo feminino</td><td>construção; edificação; edifício; fortalecimento espiritual</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-09\" data-source=\"BDAG\" data-search=\"οἰκοδομητός, ή, όν adjetivo construído; edificado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδομητός, ή, όν</td><td>adjetivo</td><td>construído; edificado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-10\" data-source=\"BDAG\" data-search=\"οἰκοδομία, ας, ἡ substantivo feminino construção; edificação; atividade de construir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδομία, ας, ἡ</td><td>substantivo feminino</td><td>construção; edificação; atividade de construir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-11\" data-source=\"BDAG\" data-search=\"οἰκοδόμος, ου, ὁ substantivo masculino construtor; edificador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοδόμος, ου, ὁ</td><td>substantivo masculino</td><td>construtor; edificador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-12\" data-source=\"BDAG\" data-search=\"οἰκονομέω verbo administrar; gerir; planejar; executar um projeto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκονομέω</td><td>verbo</td><td>administrar; gerir; planejar; executar um projeto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-13\" data-source=\"BDAG\" data-search=\"οἰκονομία, ας, ἡ substantivo feminino administração; encargo; disposição; plano divino; formação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκονομία, ας, ἡ</td><td>substantivo feminino</td><td>administração; encargo; disposição; plano divino; formação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-14\" data-source=\"BDAG\" data-search=\"οἰκονόμος, ου, ὁ substantivo masculino administrador; mordomo; tesoureiro; dispensador BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκονόμος, ου, ὁ</td><td>substantivo masculino</td><td>administrador; mordomo; tesoureiro; dispensador</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-15\" data-source=\"BDAG\" data-search=\"οἶκος, ου, ὁ substantivo masculino casa; templo; família; linhagem; patrimônio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἶκος, ου, ὁ</td><td>substantivo masculino</td><td>casa; templo; família; linhagem; patrimônio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-16\" data-source=\"BDAG\" data-search=\"οἰκουμένη, ης, ἡ substantivo feminino terra habitada; mundo; Império Romano; humanidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκουμένη, ης, ἡ</td><td>substantivo feminino</td><td>terra habitada; mundo; Império Romano; humanidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-17\" data-source=\"BDAG\" data-search=\"οἰκουργέω verbo cuidar da casa; desempenhar tarefas domésticas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκουργέω</td><td>verbo</td><td>cuidar da casa; desempenhar tarefas domésticas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-18\" data-source=\"BDAG\" data-search=\"οἰκουργός, όν adjetivo ocupado com afazeres domésticos; dedicado à casa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκουργός, όν</td><td>adjetivo</td><td>ocupado com afazeres domésticos; dedicado à casa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-19\" data-source=\"BDAG\" data-search=\"οἰκουρός, όν adjetivo que permanece em casa; doméstico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκουρός, όν</td><td>adjetivo</td><td>que permanece em casa; doméstico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0251-20\" data-source=\"BDAG\" data-search=\"οἰκοφθόρος, ον adjetivo; substantivado destruidor da casa; corruptor de famílias BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">οἰκοφθόρος, ον</td><td>adjetivo; substantivado</td><td>destruidor da casa; corruptor de famílias</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0251-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκητήριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκητήριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">οἰκητήρ</span> = <span class=\"greek\">οἰκητή</span>, «habitante», cf. <span class=\"greek\">οἰκήτωρ</span>; Eur., Democr. e posteriores; Cebes 17, 3 <span class=\"greek\">εὐδαιμόνων</span> <span class=\"greek\">οἰκ</span>.; Plut., Mor. 60b; UPZ 17a, 23 [127 b.c.]; BGU 1167, 33 [12b.c.]; POxy 235, 14, termo astrológico «casa [de Cronos=Saturno]», com <span class=\"greek\">οἶκος</span> nas linhas 15 e 16; POxy 281, 11; inscrição em GPlaumann, Ptolemais 1910 p. 35 [76/75 b.c.]; 2 Macc 11:2; En 27:2; TestSol; Jos., C. Ap. 1, 153; Tat. 13, 2), lugar onde se vive, morada, habitação; dos anjos (Ps.-Aristot., De Mundo 2, 2, o céu como <span class=\"greek\">οἰκητήριον</span> <span class=\"greek\">θεοῦ</span> ou 3, 4 <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄνω</span> <span class=\"greek\">θεῶν</span>): <span class=\"greek\">ἀπολιπεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἴδιον</span> <span class=\"greek\">οἰκ</span>., abandonar a própria morada Jd 6 (cf. POxy 235 acima; <span class=\"greek\">ἴδιον</span> <span class=\"greek\">οἰκ</span>. como em Cornutus 24 p. 45, 21; quanto ao assunto, cf. En 15:3ff; Jos., Ant. 1, 73).—O corpo glorificado de um cristão transfigurado, habitação (alternando com <span class=\"greek\">οἰκία</span>, <span class=\"greek\">οἰκοδομή</span> no versículo 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:2</a> (ver <span class=\"greek\">σκῆνος</span> e a bibliografia sob <span class=\"greek\">γυμνός</span> 1b).—DELG s.v. <span class=\"greek\">οἶκο</span> C. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκήτωρ, ορος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκήτωρ</span>, <span class=\"greek\">ορος</span>, <span class=\"greek\">ὁ</span> (ver verbete precedente; Aeschyl., Hdt. e outros; Diod S 5, 41, 2; Aelian, VH 9, 16; PLond V 1677, 27; PGM 7, 351; T. Kellis 22, 121; LXX; Philo; Jos., Ant. 14, 75, Vi. 230; Just., D. 119, 5), alguém que utiliza determinado lugar como moradia, habitante: <span class=\"greek\">ἔσονται</span> <span class=\"greek\">οἰκήτορες</span> <span class=\"greek\">γῆς</span>, habitarão a terra 1 Cl 14:4 (Pr 2:21). <span class=\"greek\">οἰκήτορε</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">ἐκείνου</span>, habitantes daquele lugar (local transcendente) ApcPt 4:17.—Frisk s.v. <span class=\"greek\">οἶκο</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Hdt. e posteriores).</p><p class=\"entry-text\">① Construção utilizada como habitação, casa.</p><p class=\"entry-text\">ⓐ Literalmente, como edifício <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a>; 7:24–27; 24:43; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:29</a>f; 13:34; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>f; 15:8; 18:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:22</a>; 1 Cl 12:6 e outros. Com <span class=\"greek\">ἀγρός</span> Hs 1:4, 8; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:29</a>. Com <span class=\"greek\">χωρίον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:34</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:14</a>; 9:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:38</a>; 7:44; 22:54. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:7</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span>, para dentro da casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:51</a>; 10:38 v.l. (provavelmente leitura original, omitida por reverência por alguns copistas: MdeJonge, NThT 34, 308 [contra Metzger 153]; ver RBorger, TRu 52, ’87, 32f); 22:10; (ir, vir) para casa (Appian, Bell. Civ. 5, 68 §288; Jos., Vi. 144) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:28</a>; 13:36; 17:25; AcPl Ha 4, 3; em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:10</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκίαν</span>, para uma casa 6:10; 7:24; para vossa casa 2J 10. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:15</a>; 14:3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:29</a>; 7:37. <span class=\"greek\">ἐν</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">τινός</span> (POxy 51, 13 <span class=\"greek\">ἐν</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">Ἐπαγαθοῦ</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:11</a>; 10:32; <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span>, na casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:35</a>; 11:31; em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:6</a>; 9:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:33</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">οἰκίᾳ</span>, numa casa ou em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:27</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span>, os que estão dentro da casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:15</a> (<span class=\"greek\">πάντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκ</span>. como em Dio Chrys. 64 [14], 7); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:32</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span>, dono da casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:35</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκοδεσπότης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:11</a>. <span class=\"greek\">κατεσθίειν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">χηρῶν</span>, devorar as casas das viúvas, isto é, roubar às viúvas suas casas (e bens domésticos; ver <span class=\"greek\">οἶκος</span> 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:13</a> [14] v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:47</a> (Maximus Tyr. 14, 4e <span class=\"greek\">κείρειν</span> [=devorar] <span class=\"greek\">οἶκον</span> <span class=\"greek\">βασιλέως</span>). <span class=\"greek\">κατοικεῖν</span> <span class=\"greek\">οἰκίας</span> <span class=\"greek\">πηλίνας</span>, morar em casas de barro 1 Cl 39:5 (Job 4:9).—KJäger, D. Bauernhaus in Palästina, m. Rücksicht auf d. bibl. Wohnhaus untersucht 1912; Dalman, Arbeit VII: D. Haus, Hühnerzucht, Taubenzucht, Bienenzucht ’42.</p><p class=\"entry-text\">ⓑ Em linguagem figurada, do corpo como habitação da alma (cf. <span class=\"greek\">σαρκικὸς</span> <span class=\"greek\">οἶκος</span> ParJer 6:6): <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐπίγειος</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σκήνους</span>, a tenda terrestre na qual vivemos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a>a. Em contraste, o corpo glorificado é chamado <span class=\"greek\">οἰκία</span> <span class=\"greek\">ἀχειροποίητος</span>, habitação não feita por mãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a>b.—Ver <span class=\"greek\">οἰκητήριον</span>.—Sobre o céu como morada de Deus (cf. Artem. 2, 68 p. 159, 13 <span class=\"greek\">ὁ</span> <span class=\"greek\">οὐρανὸς</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">οἶκος</span>; escólio sobre Aeschin. 2, 10: segundo Timeu, uma mulher sonhou que fora arrebatada ao céu, onde vira <span class=\"greek\">τὰς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">οἰκήσεις</span>; Sappho 1, 7 D.2: Afrodite habita <span class=\"greek\">πατρὸς</span> [Zeus] <span class=\"greek\">δόμον</span>.—Puramente formal UPZ 18, 8 [163 b.c.] <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἡμῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:2</a> (diferentemente OSchaefer, ZNW 32, ’33, 210–17, contra ele Bultmann 464, 5).</p><p class=\"entry-text\">② Unidade social de residentes, casa, família (X., Mem. 2, 7, 6; Diod S 12, 14, 3; 13, 96, 3; PPetr II, 23 [4], 2 <span class=\"greek\">καταγράψας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ὥρου</span>; Philo, Abr. 92; Jos., Ant. 17, 134) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:25</a> (com <span class=\"greek\">πόλις</span>, como Synes., Providence 1, 4 p. 9d); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:25</a> (com <span class=\"greek\">βασιλεία</span>). <span class=\"greek\">ἐπίστευσεν</span> <span class=\"greek\">αὐτὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὅλη</span>, ele e toda a sua família creram <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:53</a> (Appian, Bell. Civ. 1, 13 §55 <span class=\"greek\">Γράκχος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ὅλῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκίᾳ</span> <span class=\"greek\">κατάρχοιτο</span>). <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">Στεφανᾶ</span>, família de Estéfanas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:15</a>. <span class=\"greek\">ἄτιμος</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">μὴ</span> … <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">αὐτοῦ</span>, sem honra, exceto … na própria família <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.57\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:57</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:4</a>.</p><p class=\"entry-text\">③ Uma posição intermediária entre os sentidos 1 e 2 é apresentada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:12</a>f: <span class=\"greek\">εἰσερχόμενοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">ἀσπάσασθε</span> <span class=\"greek\">αὐτήν</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκία</span> <span class=\"greek\">ἀξία</span> …—<span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:22</a> quer dizer, seja traduzido «os da casa» ou «os da família do imperador», conforme o uso predominante, não membros da família ou parentesco do imperador, mas servidores em sua corte; no começo do período imperial, eram ordinariamente escravos ou libertos (cf. Philo, In Flacc. 35; Jos., Ant. 17, 142; <span class=\"greek\">παντὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">Σεβαστῶν</span> PHerrmann, Inschriften von Sardeis: Chiron 23, ’93, 234 nº 1 linha 5; MartPl 1 [Aa I 104, 8; 106, 15]. Cf. também Diog. L. 5, 75, explicação da origem «ignóbil» de Demétrio de Falero: <span class=\"greek\">ἦν</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Κόνωνος</span> <span class=\"greek\">οἰκίας</span>. Em contrapartida, Diod S 17, 35, 3 <span class=\"greek\">αἱ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλικῆς</span> <span class=\"greek\">οἰκίας</span> <span class=\"greek\">γυναῖκες</span> = mulheres da família real.—AdeWaal, <span class=\"greek\">Οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">οἰκίας</span> [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:22</a>]: Röm. Quartalschr. 26, 1912, 160–63; Zahn, Einl.3 391; GDuncan, St. Paul’s Ephesian Ministry 1929 [que apresenta a teoria do encarceramento de Paulo em Éfeso]. Ver também <span class=\"greek\">Καῖσαρ</span> ad loc.).—B. 133; 458. DELG s.v. <span class=\"greek\">οἶκο</span> A I. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκιακός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκιακός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">οἶκος</span>; Plut., Cic. 870 [20, 3]; POxy 294, 17 [22 a.d.]; PGiss 88, 4), membro de uma família ou casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:25</a> (em oposição a <span class=\"greek\">οἰκοδεσπότης</span>), 36 (aqui, família extensa, não apenas residentes na mesma casa).—DELG s.v. <span class=\"greek\">οἶκο</span> A I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδεσποτέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδεσποτέω</span> (<span class=\"greek\">οἰκοδεσπότης</span>; palavra tardia [Lob., Phryn. p. 373]; especialmente termo técnico astrológico para o «domínio» de planeta que influencia a vida humana: Plut., Mor. 90b; Ps.-Lucian, Astrol. 20; POxy 235, 16 [20/50 a.d.] <span class=\"greek\">οἰκοδεσποτεῖ</span> <span class=\"greek\">Ἀφροδίτη</span>; PLond I, 130, 163 p. 137: Stilbon, o planeta Mercúrio, «dominará o tema [do nascimento]»; Cat. Cod. Astr. IX/1 p. 158, 7), administrar a própria casa, cuidar do lar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:14</a>.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδεσπότης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδεσπότης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">δεσπότης</span>; palavra posterior [Lob., Phryn. p. 373]; Alexis Com. [IV b.c.] 225; Plut., Mor. 271e; SIG 888, 57f; New Docs 2, 58 nº 18,12 [75/76 a.d.]; inscrição isáurica em PASA III p. 150 <span class=\"greek\">υἱοὺς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οἰκοδεσπότας</span>; PLond I, 98 recto, 60 p. 130 [I/II a.d.]; PSI 158, 80 (sobre papiros astrológicos [incluindo PParis 19, 42; 75, 10f; PLond I, 110, 41 p. 132 [138 a.d.]], ver índice de Neugebauer-Hoesen); TestJob 39:2; Philo; Jos., C. Ap. 2, 128), dono da casa, senhor do lar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:39</a>. Uso pleonástico <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:11</a> (cf. SIG 985, 52 [II/I b.c.]; ver B-D-F §484). Usado com <span class=\"greek\">ἄνθρωπος</span> em figura <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:52</a>; 20:1; 21:33. Em parábolas e figuras, acerca de Deus (cf. Epict. 3, 22, 4; Philo, Somn. 1, 149) 13:27 (interpretado como o Filho do Homem no versículo 37); 20:1, 11; 21:33; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:21</a>; Hs 5, 2, 9; cf. IEph 6:1. Cristo acerca de si mesmo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:25</a> (<span class=\"greek\">δεσπότης</span> P75).—DELG s.v. <span class=\"greek\">δεσπότη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδομέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδομέω</span> (<span class=\"greek\">οἰκοδόμος</span>; Hdt.; inscrições, papiros, LXX, En, EpArist, Philo, Joseph., Test12Patr), imperfeito <span class=\"greek\">ᾠκοδόμουν</span>; futuro <span class=\"greek\">οἰκοδομήσω</span>; 1º aoristo <span class=\"greek\">ᾠκοδόμησα</span>, também sem aumento <span class=\"greek\">οἰκοδόμησα</span> (ApcMos 40; sobre o aumento, ver W-S. §12, 5a; Mlt-H. 191); perfeito <span class=\"greek\">ᾠκοδόμηκα</span> LXX; mais-que-perfeito, 3ª pessoa singular <span class=\"greek\">ᾠκοδομήκει</span> (Just., D. 127, 3). Passivo: imperfeito, 3ª pessoa singular <span class=\"greek\">ᾠκοδομεῖτο</span>; 1º futuro <span class=\"greek\">οἰκοδομηθήσομαι</span>; 1º aoristo <span class=\"greek\">ᾠκοδομήθην</span> (v.l.) ou <span class=\"greek\">οἰκοδομήθην</span> (outras edições, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:20</a>); infinitivo perfeito <span class=\"greek\">ᾠκοδομῆσθαι</span> (<span class=\"greek\">οἰ</span>-<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>b); particípio <span class=\"greek\">οἰκοδομημένος</span> (Ox 1 recto, 15f [GTh 32]); <span class=\"greek\">ᾠκοδομημένος</span> Hv 3, 2, 6; mais-que-perfeito, 3ª pessoa singular <span class=\"greek\">ᾠκοδόμητο</span>.</p><p class=\"entry-text\">① Construir edifício, edificar.</p><p class=\"entry-text\">ⓐ Com acusativo de objeto: construir, erguer (frequente nos papiros [Mayser II/2 p. 315, 30ff]; Jos., Ant. 15, 403 e outros; Did., Gen 29, 7): <span class=\"greek\">οἰκίαν</span> (Diod S 14, 116, 8; Lucian, Charon 17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>a. <span class=\"greek\">τὰς</span> <span class=\"greek\">οἰκοδομάς</span> GJs 9:3; passivo (Sb 5104, 2 [163 b.c.] <span class=\"greek\">οἰκία</span> <span class=\"greek\">ᾠκοδομημένη</span>; PAmh 51, 11; 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>b. <span class=\"greek\">πύργον</span> (Is 5:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:28</a>; Hs 9, 3, 1; 4; 9, 12, 6; passivo Hv 3, 2, 4ff; 3, 3, 3; 3, 5, 5; 3, 8, 9; Hs 9, 3, 2; 9, 5, 2; 9, 9, 7; cf. 9, 9, 4. <span class=\"greek\">ναόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:58</a>; 16:3 (Is 49:17); passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:20</a> (Heliodorus Periegeta of Athens [II b.c.]: 373 Fgm. 1 Jac. diz sobre a Acrópole: <span class=\"greek\">ἐν</span> <span class=\"greek\">ἔτεσι</span> <span class=\"greek\">ε</span>̄ <span class=\"greek\">παντελῶς</span> <span class=\"greek\">ἐξεποιήθη</span>; Orig., C. Cels. 5, 33, 13); 16:6 (cf. abaixo; a passagem «escriturística» é interpretada espiritualmente). <span class=\"greek\">ἀποθήκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:18</a> (em oposição a <span class=\"greek\">καθαιρεῖν</span>; ver este verbo, 2a<span class=\"greek\">α</span>). <span class=\"greek\">τοὺς</span> <span class=\"greek\">τάφους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>, os túmulos dos profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:29</a> (ver EKlosterman2 ad loc.). <span class=\"greek\">τὰ</span> <span class=\"greek\">μνημεῖα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span>, os monumentos dos profetas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.47\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:47</a> (<span class=\"greek\">μνημεῖον</span> 1).—<span class=\"greek\">οἰκ</span>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span>, construir alguma coisa para alguém (Gen 8:20; Ex 1:11; Ezk 16:24): <span class=\"greek\">συναγωγὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τινί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:5</a>. <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τινὶ</span> <span class=\"greek\">οἶκον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:47</a>, 49; 16:2 (os dois últimos Is 66:1).—Com acusativo de objeto e, em seguida, <span class=\"greek\">ἐπί</span> com acusativo ou genitivo: <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πέτραν</span>, construir casa sobre a rocha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:24</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄμμον</span>, sobre a areia, versículo 26 (proverbial: Plut. VII p. 463, 10 Bern. <span class=\"greek\">εἰς</span> <span class=\"greek\">ψάμμον</span> <span class=\"greek\">οἰκοδομεῖς</span>). <span class=\"greek\">πόλις</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὄρους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:29</a> (cf. Jos., Ant. 8, 97). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> 6:49. <span class=\"greek\">πόλις</span> <span class=\"greek\">οἰκοδομημένη</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἄκρον</span> <span class=\"greek\">ὄρους</span> <span class=\"greek\">ὑψηλοῦ</span>, cidade construída no cume de alto monte Ox 1 recto, 15f (GTh 32). <span class=\"greek\">πύργος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ὑδάτων</span> Hv 3, 3, 5; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πέτραν</span> Hs 9, 14, 4 (em oposição a <span class=\"greek\">χαμαὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ᾠκοδόμηται</span>).</p><p class=\"entry-text\">ⓑ Emprego absoluto.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Quando o objeto pode ser suprido pelo contexto (Did., Gen. 33, 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:48</a>; 14:30.—Cf. Hv 3, 1, 7; 3, 4, 1a; 3, 10, 1; Hs 9, 4, 1.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Mas também completamente sem objeto (Theoph. Ant. 2, 13 [p. 132, 4f]): <span class=\"greek\">ᾠκοδόμουν</span>, construíam edifícios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:28</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκοδομοῦντες</span>, construtores, pedreiros (segundo Ps 117:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:11</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a>; 6:4. Também sem alusão à passagem do salmo: Hs 9, 4, 4; 9, 6, 6.</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ἤδη</span> <span class=\"greek\">ᾠκοδομημένοι</span>, as pedras já empregadas na construção Hv 3, 5, 2; cf. Hs 9, 6, 3.</p><p class=\"entry-text\">ⓒ Reconstruir, restaurar, sentido que <span class=\"greek\">οἰκ</span>. pode receber do contexto (Josh 6:26; Ps 50:20; 68:36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:61</a>; 27:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:29</a>; 16:3 (Is 49:17).—Ver também 2.</p><p class=\"entry-text\">② Construir em sentido transcendente (como nas passagens de Hermas mencionadas em 1, nas quais a torre simboliza a igreja), edificar: acerca da edificação da comunidade/congregação cristã (cf. Ruth 4:11; <span class=\"greek\">θεμελιώσαντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οἰκοδομήσαντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">μακάριοι</span> <span class=\"greek\">ἀπόστολοι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span> Iren. 3, 3, 3 [Harv. II 10, 1]): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ταύτῃ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πέτρᾳ</span> <span class=\"greek\">οἰκοδομήσω</span> <span class=\"greek\">μου</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐκκλησίαν</span>, sobre esta rocha edificarei a minha congregação/igreja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:18</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">οἰκοδομεῖσθε</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">πνευματικός</span>, como pedras vivas, deixai-vos edificar (passivo) ou edificai-vos (médio, assim Goodsp., Probs. 194f) em casa espiritual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:5</a>. Paulo se refere ao trabalho missionário onde outro cristão já iniciara atividades como <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">ἀλλότριον</span> <span class=\"greek\">θεμέλιον</span> <span class=\"greek\">οἰκ</span>., edificar sobre fundamento alheio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:20</a>. Também descreve sua avaliação negativa da lei em relação ao evento de Cristo como construção e fala de sua refutação como demolição (<span class=\"greek\">καταλύειν</span>) e de seu retorno como reconstrução (ver 1c acima) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:18</a>. Provavelmente é aqui que se enquadra 11:1: após citações das Escrituras, diz-se acerca dos israelitas que não aceitam o batismo que remove pecado, mas <span class=\"greek\">ἑαυτοῖς</span> <span class=\"greek\">οἰκοδομήσουσιν</span>, edificarão algo para si. Em outra passagem B designa o crente <span class=\"greek\">πνευματικὸς</span> <span class=\"greek\">ναὸς</span> <span class=\"greek\">οἰκοδομούμενος</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, templo espiritual construído para o Senhor 16:10; cf. versículos 6f.—O discurso de Hermas sobre a construção do templo menciona anjos encarregados por Deus de <span class=\"greek\">οἰκοδομεῖν</span>, construir ou completar toda a sua criação Hv 3, 4, 1b.—(Nesse contexto, cf. Orig., C. Cels. 4, 38, 16 <span class=\"greek\">γυνὴ</span> <span class=\"greek\">οἰκοδομηθεῖσα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> [sobre Eva]).</p><p class=\"entry-text\">③ Ajudar a melhorar a capacidade de viver responsável e eficazmente, fortalecer, edificar, tornar mais apto. <span class=\"greek\">οἰκ</span>. é assim empregado em sentido não literal, muitas vezes sem consciência da acepção primária (Straub p. 27), algo semelhante a «edificar» na linguagem moral (esse emprego estendido já ocorre em X., Cyr. 8, 7, 15 e na LXX: Ps 27:5; Jer 40:7. Também TestBenj 8:3.—JWeiss sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:1</a>). Acerca do Senhor, que é capaz de fortalecer os crentes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.32\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:32</a>. Da congregação, que estava sendo edificada 9:31.—Especialmente em Paulo: <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">οἰκοδομεῖ</span>, o amor edifica (em oposição a <span class=\"greek\">γνῶσις</span>, que «incha») <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:1</a> (=Dg 12:5). <span class=\"greek\">πάντα</span> <span class=\"greek\">ἔξεστιν</span>, <span class=\"greek\">ἀλλ</span>’ <span class=\"greek\">οὐ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">οἰκοδομεῖ</span>, tudo é permitido, mas nem tudo é proveitoso 10:23. <span class=\"greek\">ὁ</span> <span class=\"greek\">λαλῶν</span> <span class=\"greek\">γλώσσῃ</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">οἰκοδομεῖ</span>· <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">προφητεύων</span> <span class=\"greek\">ἐκκλησίαν</span> <span class=\"greek\">οἰκοδομεῖ</span> 14:4; cf. versículo 17. <span class=\"greek\">οἰκοδομεῖτε</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἕνα</span>, fortalecei-vos uns aos outros <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:11</a>. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:10</a> o apóstolo provavelmente fala ironicamente, em referência ao partido dos «fortes» em Corinto, que declaram estar, pelo seu exemplo, beneficiando os «fracos»: <span class=\"greek\">οὐχὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">συνείδησις</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οἰκοδομηθήσεται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">εἰδωλόθυτα</span> <span class=\"greek\">ἐσθίειν</span>; não será sua consciência «fortalecida» para comer carne oferecida a ídolos? (diferentemente MargaretThrall, TU 102, ’68, 468–72).—Acerca das cartas de Paulo, pelas quais <span class=\"greek\">δυνηθήσεσθε</span> <span class=\"greek\">οἰκοδομεῖσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δοθεῖσαν</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πίστιν</span>, podereis edificar-vos na fé que vos foi dada Pol 3:2.—HCremer, Über den bibl. Begriff der Erbauung 1863; HScott, The Place of <span class=\"greek\">οἰκοδομή</span> in the NT: PT 2, 1904, 402–24; HBassermann, Über den Begriff ‘Erbauung’: Zeitschr. für prakt. Theol. 4 1882, 1–22; CTrossen, Erbauen: ThGl 6, 1914, 804ff; PVielhauer, Oikodome (d. Bild vom Bau vom NT bis Clem. Alex.), dissertação, Heidelberg ’39; PBonnard, Jésus-Christ édifiant son Église ’48.—B. 590. DELG s.v. <span class=\"greek\">δέμω</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδομή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδομή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">δέμω</span>, «construir»; rejeitado pelos aticistas [Lob., Phryn. 421; 487ff; WSchmid, Der Attizismus III 1893, 248], mas encontrado desde Aristot., EN 5, 14, 7; Diod S 1, 46, 4; Plut., Lucull. 518 [39, 2]; IG XIV, 645, 146 [dórico]; OGI 655, 2 [25 b.c.]; PGrenf I, 21, 17 [126 b.c.]; BGU 699, 3; 894, 2; LXX; En; TestSol; Philo, Mos. 1, 224 v.l., Spec. Leg. 1, 73 v.l.; Joseph. [Schmidt 528f]; Just., D. 86, 6).</p><p class=\"entry-text\">① Processo de construir, construção, edificação.</p><p class=\"entry-text\">ⓐ Literalmente (2 Ch 3:2 v.l.; Sir 40:19; Jos., Ant. 11, 59; ViHg 1 [p. 87, 18 Sch.]; Jos., Ant. 11, 59; Theoph. Ant. 3, 22 [p. 246, 24]; Did., Gen. 33, 27): <span class=\"greek\">ἐτελέσθη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκοδομή</span>, a construção foi concluída Hs 9, 5, 1a. <span class=\"greek\">ἀνοχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>., atraso na construção, ibidem b; 9, 14, 2. Hv 3, 2, 8 provavelmente pertence a 2a.</p><p class=\"entry-text\">ⓑ Figuradamente, acerca de fortalecimento espiritual (ver <span class=\"greek\">οἰκοδομέω</span> 3), edificar, edificação, fortalecimento.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Ativo, com genitivo objetivo: <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐκκλησίας</span>, para a edificação da igreja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:12</a>. <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">οἰκ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:19</a>. Em emprego absoluto: <span class=\"greek\">πρὸς</span> <span class=\"greek\">οἰκοδομήν</span>, para edificação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:26</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.29\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:29</a> (Straub 36). Paulo recebeu sua autoridade do Senhor <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">καθαίρεσιν</span>, para edificação e não para demolição <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:10</a>; cf. 10:8. <span class=\"greek\">τὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀλλήλους</span>, aquilo que favorece a edificação mútua <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:19</a>. As cartas de Inácio contêm <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">οἰκοδομήν</span> Pol 13:2. Abstrato em lugar do concreto: <span class=\"greek\">ὁ</span> <span class=\"greek\">προφητεύων</span> <span class=\"greek\">λαλεῖ</span> <span class=\"greek\">οἰκοδομήν</span>, quem profetiza profere palavras edificantes <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:3</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Passivo: <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">λαβεῖν</span>, receber edificação, ser edificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:5</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">σώματος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Χριστοῦ</span>, para que o corpo de Cristo seja edificado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:12</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἑαυτοῦ</span>, para sua própria edificação, versículo 16 (quanto à gramática, cf. TestJob 11:5 <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πτωχῶν</span>).</p><p class=\"entry-text\">② Edifício como resultado de processo de construção, construção, edifício.</p><p class=\"entry-text\">ⓐ Literalmente; plural, acerca de construções seculares (Diod S 16, 76, 2; 20, 8, 3) Hs 1:1 (com <span class=\"greek\">ἀγροί</span>, <span class=\"greek\">παρατάξεις</span>, <span class=\"greek\">οἰκήματα</span>); GJs 9:3; 13:1. Especialmente sobre construções do templo (1 Esdr 5:70): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἐλπίζειν</span>, pôr esperança apenas no edifício 16:1. Plural, de diversas construções na área do templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:1</a>f. <span class=\"greek\">αἱ</span> <span class=\"greek\">οἰκοδομαὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἱεροῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:1</a>. Emprego especialmente frequente nas imagens da torre em Hermas (v 3; Hs 9). Entretanto, em muitas passagens o sentido 1a também é provável: <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, construção da torre (ou edifício da torre) Hv 3, 2, 6b; 3, 4, 1f; 3, 5, 1b; 3, 12, 3; Hs 9, 1, 2; 9, 3, 3; 9, 4, 2ff; 9, 5, 2; 9, 17, 4 e outros. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐξώτερα</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>., parte externa da construção Hs 9, 9, 3b. Acerca das pedras: <span class=\"greek\">εὔχρηστοι</span> <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὴν</span>) <span class=\"greek\">οἰκ</span>. v 3, 5, 5; 3, 6, 1; 6; também <span class=\"greek\">εὔχρηστοι</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">οἰκ</span>. Hs 9, 15, 6. <span class=\"greek\">χρήσιμοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> v 4, 3, 4. <span class=\"greek\">ἀπενεχθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 8, 3a. <span class=\"greek\">ἀπέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 5, 3f; 9, 7, 4a; 6f; 9, 10, 2. <span class=\"greek\">ἀποβάλλεσθαι</span> <span class=\"greek\">ἐκ</span> (<span class=\"greek\">ἀπὸ</span>) <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. Hs 9, 7, 1; 9, 8, 3b; 9, 9, 5. <span class=\"greek\">ἀποδοκιμάζειν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. Hs 9, 12, 7; passivo (sem <span class=\"greek\">ἐκ</span>) 9, 23, 3; <span class=\"greek\">ἁρμόζειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. v 3, 6, 5; 3, 7, 5; passivo Hs 9, 4, 3; 9, 8, 5ff; 9, 9, 4; 9, 15, 4. <span class=\"greek\">βάλλειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 7, 4; 6; 9, 8, 2a; passivo 9, 7, 5; 9, 10, 1; 9, 30, 2. <span class=\"greek\">δοκιμάζειν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 5, 2b. <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 12, 4; 9, 13, 4. <span class=\"greek\">ἐκλέγεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 9, 3a. <span class=\"greek\">ἐπιδιδόναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 4, 5; 8; 9, 15, 5; passivo 9, 4, 6. <span class=\"greek\">ἐπιθυμεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 9, 7. <span class=\"greek\">ἐπιτίθεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. v 3, 5, 2. <span class=\"greek\">ἐργάζεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>., trabalhar na construção Hs 9, 6, 2b. <span class=\"greek\">εὑρεθῆναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 6, 4. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐφεστὼς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. Hs 9, 6, 2a. <span class=\"greek\">κατανοεῖν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>., examinar o edifício Hs 9, 5, 7; 9, 6, 3. <span class=\"greek\">συναρμόζεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> Hs 9, 16, 7. <span class=\"greek\">τιθέναι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. v 3, 2, 6a; 7; Hs 9, 7, 2; 9, 8, 2b; passivo v 3, 5, 4; Hs 9, 6, 8; 9, 8, 4; 9, 9, 2; 9, 13, 6; 9, 16, 1; 9, 17, 3; 9, 29, 4; 9, 30, 1. <span class=\"greek\">τίθεσθαι</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. Hs 9, 8, 1. <span class=\"greek\">ὑπάγειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. v 3, 5, 1a; 3; 3, 6, 2; Hs 9, 3, 3f. <span class=\"greek\">χρᾶσθαι</span> <span class=\"greek\">εἰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. v 3, 2, 8.</p><p class=\"entry-text\">ⓑ Hermas oscila entre usos literais e não literais de <span class=\"greek\">οἰκ</span>., mas as passagens seguintes são claramente não literais (<span class=\"greek\">οἱ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστιανισμοῦ</span> Orig., C. Cels. 3, 28, 8): <span class=\"greek\">θεοῦ</span> <span class=\"greek\">οἰκοδομή</span> <span class=\"greek\">ἐστε</span>, sois edifício de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:9</a> (AFridrichsen [ver <span class=\"greek\">γεώργιον</span>]; sobre a imagem, Straub 85–88). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:21</a>, a comunidade cristã é chamada <span class=\"greek\">οἰκοδομή</span>, mais precisamente <span class=\"greek\">ναὸς</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, erigido sobre o fundamento dos apóstolos e profetas, tendo Cristo Jesus como pedra angular (HSchlier, Christus u. d. Kirche im Eph 1930).—Dos cristãos: <span class=\"greek\">ὄντες</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">ναοῦ</span> <span class=\"greek\">πατρὸς</span> <span class=\"greek\">ἡτοιμασμένοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">πατρός</span>, sendo pedras do templo do Pai preparadas para a construção de Deus Pai IEph 9:1.—Figuradamente, de outra maneira, sobre o corpo glorificado do cristão falecido: <span class=\"greek\">οἰκοδομὴν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔχομεν</span>, <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">ἀχειροποίητον</span>, temos edifício proveniente de Deus, casa não feita por mãos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:18</a> v.l. (em lugar de <span class=\"greek\">ἐνδώμησις</span>). Ver <span class=\"greek\">οἰκητήριον</span> 2.—Bibliografia sob <span class=\"greek\">οἰκοδομέω</span>, no final.—DELG s.v. <span class=\"greek\">δέμω</span>. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδομητός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδομητός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">οἰκοδομή</span>; Strabo 3, 3, 7; 8, 6, 2; Etym. Mag. p. 282, 46; 453, 33), construído: <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ναὸς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">χειρός</span>, templo construído por mãos 16:7.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδομία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδομία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">οἰκοδομέω</span>; desde Thu. 1, 93, 1; 2, 65, 2; Pla.; Polyb. 10, 22, 7; Plut., Pomp. 654 [66, 1]; Lucian, Hist. Conscr. 4; Jos., Ant. 11, 7; 118; SIG 144, 32 [IV b.c.]; 204, 26f e outros; OGI 483, 104; 107; PHal 1, 181 [III b.c.]; PSI 500, 3; 4.—Lob., Phryn. p. 487), construção, tanto como processo quanto como resultado; em nossa literatura somente uma vez, como variante de leitura, e em sentido figurado, edificação: <span class=\"greek\">ἐκζητήσεις</span> <span class=\"greek\">παρέχουσιν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οἰκοδομίαν</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a> v.l. (em lugar de <span class=\"greek\">οἰκονομίαν</span>; D, Irineu e outros têm <span class=\"greek\">οἰκοδομήν</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοδόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοδόμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">δέμω</span>, «construir»; Hdt. e outros; Galen, Protr. 13 p. 42, 17, João [com <span class=\"greek\">τέκτων</span>]; Lucian, Icarom. 19; OGI 770, 7; papiros, LXX; Jos., Ant. 7, 66 [com <span class=\"greek\">τέκτων</span>]), construtor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:11</a>.—DELG s.v. <span class=\"greek\">δέμω</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκονομέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκονομέω</span> (<span class=\"greek\">οἰκονόμος</span>, de <span class=\"greek\">οἶκο</span> + <span class=\"greek\">νέμω</span>), particípio perfeito <span class=\"greek\">οἰκονομηκώς</span> (sobre o significado de <span class=\"greek\">οἰκ</span>. e seus derivados, ver ARobinson sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:10</a>).</p><p class=\"entry-text\">① Administrar uma casa, gerir, administrar, em emprego absoluto; exercer o ofício de um <span class=\"greek\">οἰκονόμος</span> (ver esse verbete, 1), ser administrador (Astrampsychus p. 8 Dec. 1, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:2</a>.</p><p class=\"entry-text\">② Administrar a realização de um projeto, gerir, regular, administrar, planejar (Soph., Pla. e outros; inscrições, papiros; 3 Macc 3:2; TestSol, EpArist, Iren.), com <span class=\"greek\">τὶ</span>, alguma coisa (Jos., Ant. 1, 19); acerca de Deus (<span class=\"greek\">οἰ</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">πράγματα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεό</span> Orig., C. Cels. 6, 79, 38; Did.): <span class=\"greek\">πάντα</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παιδὶ</span> <span class=\"greek\">οἰκονομηκώς</span>, depois de (Deus) ter planejado tudo com o Filho Dg 9:1 (Maximus Tyr. 27, 8a <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πᾶν</span> <span class=\"greek\">τοῦτο</span>; M. Ant. 5, 32; Philo, Decal. 53 [<span class=\"greek\">θεὸς</span>] <span class=\"greek\">οἰκονομεῖ</span> <span class=\"greek\">σωτηρίως</span> <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">σύμπαντα</span>).—New Doc 4, 144. DELG s.v. <span class=\"greek\">νέμω</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκονομία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκονομία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">οἰκονομέω</span>; X., Pla. e posteriores; inscrições, papiros; Is 22:19, 21; TestJob, ParJer, Philo, Joseph.).</p><p class=\"entry-text\">① Responsabilidade de gestão, administração de uma casa, direção, ofício (X., Oec. 1, 1; Herodian 6, 1, 1; Jos., Ant. 2, 89; PTebt 27, 21 [114 b.c.]; PLond III, 904, 25 p. 125 [104 a.d.]; Orig., C. Cels. 8, 57, 22).</p><p class=\"entry-text\">ⓐ Literalmente, sobre a atividade do <span class=\"greek\">οἰκονόμος</span>, «administrador da propriedade», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:2</a>–4 (a passagem demonstra que nem sempre é possível distinguir nitidamente o ofício das atividades a ele relacionadas).—WPöhlmann, Der verlorene Sohn u. das Haus ’93.</p><p class=\"entry-text\">ⓑ Paulo aplica a ideia de administração ao ofício apostólico: <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">πεπίστευμαι</span>, foi-me confiada uma incumbência/tarefa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:17</a> (cf. Theoph. Ant. 1, 11 [p. 82, 8]); <span class=\"greek\">ἀνθρωπίνων</span> <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">πεπίστευνται</span>, foi-lhes confiada a administração de mistérios meramente humanos Dg 7:1. Acerca de um supervisor (bispo): <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">πέμπει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκοδεσπότης</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἰδίαν</span> <span class=\"greek\">οἰκ</span>. (<span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἰδίου</span> <span class=\"greek\">οἴκου</span>), aquele que o senhor da casa enviou para administrar sua própria casa IEph 6:1. Provavelmente também aqui se inclui <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">δοθεῖσάν</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span>, conforme o encargo divino que me foi dado para vós <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:25</a>, e <span class=\"greek\">ἠκούσατε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χάριτος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δοθείσης</span> <span class=\"greek\">μοι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑμᾶς</span>, ouvistes falar da administração da graça de Deus que me foi confiada em vosso favor <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:2</a> (por outro lado, este versículo pode ser paralelo ao emprego do versículo 9; ver 2b abaixo).</p><p class=\"entry-text\">② Estado de algo organizado, disposição, ordem, plano (X., Cyr. 5, 3, 25; Polyb. 4, 67, 9; 10, 16, 2; Diod S 1, 81, 3).</p><p class=\"entry-text\">ⓐ <span class=\"greek\">ἡ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">οἰκονομία</span>, disposição ou estrutura das partes do corpo sob a pele; ficam expostas pelos açoites MPol 2:2.—(Iren. 5, 3, 2 [Harv. II, 326, 3]).</p><p class=\"entry-text\">ⓑ Acerca do plano singular de Deus, plano reservado, plano da salvação, isto é, disposições para a redenção dos seres humanos (nos papiros, relativo a disposições e instruções das autoridades: UPZ 162 IX, 2 [117 b.c.]; CPR 11, 26, e nos PGM [por exemplo 4, 293], a medidas pelas quais se pretende alcançar alguma finalidade com auxílio sobre-humano.—Just., D. 31, 1 <span class=\"greek\">τοῦ</span> <span class=\"greek\">πάθους</span> … <span class=\"greek\">οἰκ</span>.; Hippol., Did.): <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">μυστηρίου</span>, plano do mistério <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:9</a> (variante <span class=\"greek\">κοινωνία</span>; quanto à ideia, cf. versículo 2 e ver JReumann, NovT 3, ’59, 282–92.—Just., D. 134, 2 <span class=\"greek\">οἰκονομίαι</span> … <span class=\"greek\">μυστηρίων</span>). Também na passagem linguisticamente difícil 1:10, <span class=\"greek\">οἰκ</span>. certamente se refere ao plano de salvação que Deus realiza por meio de Cristo na plenitude dos tempos. <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">θεοῦ</span>, segundo o plano redentor de Deus IEph 18:2 (cf. Ath. 21, 4 <span class=\"greek\">κατὰ</span> <span class=\"greek\">θείαν</span> <span class=\"greek\">οἰκ</span>.—Plural: Iren. 1, 10, 1 [Harv. I 90, 8]): <span class=\"greek\">προσδηλώσω</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">ἠρξάμην</span> <span class=\"greek\">οἰκονομίας</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">καινὸν</span> <span class=\"greek\">ἄνθρωπον</span> <span class=\"greek\">Ἰησοῦν</span> <span class=\"greek\">Χριστόν</span>, explicar-vos-ei mais sobre o plano divino do qual comecei a tratar, com referência ao novo ser humano Jesus Cristo IEph 20:1. AcPl Ha 3, 23, acerca do maravilhoso plano de Deus, isto é, de seu modo de agir; 6, 26 <span class=\"greek\">ο</span>̣<span class=\"greek\">ἰ</span>̣<span class=\"greek\">κο</span>̣<span class=\"greek\">ν</span>̣[<span class=\"greek\">ομίαν</span> <span class=\"greek\">πληρῶσω</span> <span class=\"greek\">κτλ</span>.] (para que eu cumpra o) plano (de Deus para mim); plural 5, 27 [<span class=\"greek\">ὡς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">οἰκο</span>]<span class=\"greek\">νομίας</span> <span class=\"greek\">πληρῶσε</span> (=<span class=\"greek\">πληρῶσαι</span>), [Paulo partiu para cumprir] o propósito [de Deus também ali] (na Macedônia) (aparentemente referência às diversas incumbências missionárias dadas por Deus a Paulo; quanto à formulação, cf. <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τελέσας</span> Orig., C. Cels. 2, 65, 4).</p><p class=\"entry-text\">ⓒ Também acerca das disposições de Deus na natureza, plural: <span class=\"greek\">αἱ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">θεοῦ</span> Dg 4:5 (cf. Tat. 12, 2; 18, 2 <span class=\"greek\">ὕλης</span> <span class=\"greek\">οἰκ</span>.; Did., Gen. 92, 6 <span class=\"greek\">πάντα</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἐστίν</span>.—Sobre a ordem na criação, Theoph. Ant. 2, 12 [p. 130, 2]).</p><p class=\"entry-text\">③ Programa de instrução, formação (no caminho da salvação); este significado (também encontrado em Clem. Alex., Paed. 1, 8, 69, 3; 70, 1 p. 130 St.) parece o mais adequado a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:4</a>, onde se diz acerca dos ensinamentos errôneos de certas pessoas: <span class=\"greek\">ἐκζητήσεις</span> <span class=\"greek\">παρέχουσιν</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span>, promovem especulações inúteis em vez da formação divina que se dá na fé (<span class=\"greek\">οἰκοδομήν</span> e <span class=\"greek\">οἰκοδομίαν</span> [ver este verbete], como variantes de leitura, são apenas «correções» para atenuar a dificuldade). Se <span class=\"greek\">οἰκ</span>. for tomado no sentido de 1b acima, o pensamento do versículo seria aproximadamente: «a investigação especulativa interminável apenas provoca contendas, em lugar da realização do propósito de Deus, que diz respeito à fé».—OLillger, Das patristische Wort, dissertação Erlangen ’55; JReumann, The Use of <span class=\"greek\">ΟΙΚΟΝΟΜΙΑ</span> and Related Terms etc., dissertação U. of Pennsylvania ’57.—DELG s.v. <span class=\"greek\">νέμω</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκονόμος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκονόμος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">νέμω</span>, «administrar»; Aeschyl. e posteriores; inscrições, papiros, LXX; TestJos 12:3 [manuscritos bdg]; ParJer 7:2; Philo, Praem. 113; Joseph.; Just.. D. 125, 2; Tat.; empréstimo no rabínico).</p><p class=\"entry-text\">① Administrador de casa ou propriedade, mordomo, administrador (Diod S 36, 5, 1): <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστὸς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">φρόνιμος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a>. Semelhantemente <span class=\"greek\">ζητεῖται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">πιστός</span> <span class=\"greek\">τις</span> <span class=\"greek\">εὑρεθῇ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:2</a>. Ele administra os bens de seu senhor (cf. Jos., Ant. 12, 200; Artem. 4, 28. Os <span class=\"greek\">οἰκ</span>. de diversas pessoas são mencionados nos papiros: PTebt 402, 1; POxy 929, 25; sobre <span class=\"greek\">οἰκ</span>. de empregadoras, ver New Docs, fim do verbete) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:1</a>, 3. <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀδικίας</span>, administrador desonesto (cf. Lucian, Ep. Sat. 2, 26 <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ὑφελόμενος</span>; ÉDelebecque, Études grecques sur l’Évangile de Luc ’76, 89–97), versículo 8 (sobre o «mordomo injusto», ver Jülicher, Gleichn. 495–514; LFonck, D. Parabel3 1919 [bibliografia ali, 675f]; ARücker, Bibl. Studien XVII/5, 1912; JKögel, BFCT XVIII/6, 1914; ERiggenbach, Schlatter Festschr. 1922, 17ff; FTillmann, BZ 9, 1911, 171–84; GKrüger, ibid. 21, ’33, 170–81; FHüttermann, ThGl 27, ’35, 739–42; HPreisker, TLZ 74, ’49, 85–92; JJeremias, Gleichnisse Jes2 ’52, 30–33; JDerrett, Law in the NT, ’70, 48–77; DFletcher, JBL 82, ’63, 15–30; JFitzmyer, Theological Studies 25, ’64, 23–42; DIreland, Stewardship and the Kingdom of God: An Historical, Exegetical, and Contextual Study of the Parable of the Unjust Steward in Luke 16:1–3 ’92). Com <span class=\"greek\">ἐπίτροπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:2</a> (SBelkin, JBL 54, ’35, 52–55).</p><p class=\"entry-text\">② Tesoureiro público, tesoureiro: <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>, o tesoureiro da cidade (SIG 1252 <span class=\"greek\">πόλεως</span> <span class=\"greek\">Κῴων</span> <span class=\"greek\">οἰκονόμος</span>; outros exemplos em PLandvogt, Epigr. Untersuchungen üb. den <span class=\"greek\">οἰκονόμος</span>, dissertação Strassb. 1908; HCadbury, JBL 50, ’31, 47ff) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:23</a>.</p><p class=\"entry-text\">③ Alguém incumbido de administração relativa a assuntos transcendentes, administrador (Aristot., Rhet. 3, 3 p. 1406a, 27 <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκουόντων</span> <span class=\"greek\">ἡδονῆς</span>; Tat. 9, 3 <span class=\"greek\">τῆς</span> <span class=\"greek\">εἱμαρμένης</span> <span class=\"greek\">οἰκ</span>.), acerca de administradores das coisas divinas (<span class=\"greek\">Βαροὺχ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> ParJer 7:2; sobre ofício no Serapeu UPZ 56, 7 [160 b.c.]; associações religiosas também possuíam <span class=\"greek\">οἰκ</span>.: OGI 50, 12; 51, 26): os apóstolos são <span class=\"greek\">οἰκονόμοι</span> <span class=\"greek\">μυστηρίων</span> <span class=\"greek\">θεοῦ</span>, administradores dos desígnios/planos secretos de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:1</a>. Assim o supervisor de uma comunidade cristã deve comportar-se como <span class=\"greek\">θεοῦ</span> <span class=\"greek\">οἰκ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:7</a>. Mas também os cristãos em geral são <span class=\"greek\">θεοῦ</span> <span class=\"greek\">οἰκ</span>. (<span class=\"greek\">καὶ</span> <span class=\"greek\">πάρεδροι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὑπηρέται</span>) IPol 6:1, ou <span class=\"greek\">καλοὶ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ποικίλης</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">θεοῦ</span>, bons administradores da multiforme graça de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:10</a> (cf. X., Mem. 3, 4, 7 <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀγαθοὶ</span> <span class=\"greek\">οἰκ</span>.).—JReumann, JBL 77, ’58, 339–49 (pré-cristão), ‘Jesus the Steward’, TU 103, ’68, 21–29.—New Docs 4, 160f. DELG s.v. <span class=\"greek\">νέμω</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἶκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἶκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. e posteriores).</p><p class=\"entry-text\">① Casa.</p><p class=\"entry-text\">ⓐ Literalmente.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Habitação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:17</a> (cf. <span class=\"greek\">πίπτω</span> 1b<span class=\"greek\">β</span>); 12:39; 14:23 (a menos que <span class=\"greek\">οἶκ</span>. signifique aqui sala de refeições, como em Phryn. Com. [V b.c.] 66 Kock; X., Symp. 2, 18; Athen. 12, 54a); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2</a>; (com <span class=\"greek\">ἀγροί</span>, <span class=\"greek\">κτήματα</span>) Hs 1:9. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">τινος</span>, para dentro da casa ou até a casa de alguém (Judg 18:26): <span class=\"greek\">ἀπέρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:23</a>; 5:25; <span class=\"greek\">εἰσέρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:40</a>; 7:36; 8:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:12</a>; 16:15b; <span class=\"greek\">ἔρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:38</a>; <span class=\"greek\">καταβαίνειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:14</a>; <span class=\"greek\">πορεύεσθαι</span> 5:24; <span class=\"greek\">ὑπάγειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:11</a>; 5:19; <span class=\"greek\">ὑποστρέφειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:56</a>; 8:39.—<span class=\"greek\">κατοικεῖν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">τινος</span>, morar na casa de alguém Hm 4, 4, 3; Hs 9, 1, 3. <span class=\"greek\">οἱ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">μου</span>, os membros de minha casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.61\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:61</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> … <span class=\"greek\">οἶκον</span> <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">χαρά</span> AcPl Ha 6, 2.—<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>, para dentro da casa, para casa: <span class=\"greek\">ἀνάγειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:34</a>. <span class=\"greek\">ἀπέρχεσθαι</span> Hs 9, 11, 2. <span class=\"greek\">ἔρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:6</a>. <span class=\"greek\">ὑπάγειν</span> Hs 9, 11, 6. <span class=\"greek\">ὑποστρέφειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:10</a>.—<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> (com <span class=\"greek\">ὐποδέχεσθαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:38</a> v.l. (ver <span class=\"greek\">οἰκία</span> 1a).—<span class=\"greek\">εἰς</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">τινος</span>, para a casa de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 8:3</a>, 26. <span class=\"greek\">εἰς</span> <span class=\"greek\">οἶκόν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀρχόντων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:1</a> (sobre a ausência do artigo, ver B-D-F §259, 1; Rob. 792).—<span class=\"greek\">εἰς</span> <span class=\"greek\">οἶκον</span>, para casa (Aeschyl., Soph.; Diod S 4, 2, 1): <span class=\"greek\">εἰσέρχεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:17</a>; 9:28. <span class=\"greek\">ἔρχεσθαι</span> 3:20.—<span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">ἐκείνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">τινός</span>, na casa de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:20</a>; 10:30; 11:13; Hs 6, 1, 1.—<span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span>, na casa, em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:20</a>; Hv 5:1.—<span class=\"greek\">ἐν</span> <span class=\"greek\">οἴκῳ</span>, em casa (Strabo 13, 1, 38; UPZ 59, 5 [168 b.c.]; 74, 6; POxy 531, 3 [II a.d.]; 1 Km 19:9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:1</a> (Goodsp., Probs. 52); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:34</a>; 14:35.—<span class=\"greek\">κατὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οἴκους</span> <span class=\"greek\">εἰσπορεύεσθαι</span>, entrar de casa em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:3</a>. <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἴκους</span> (em oposição a <span class=\"greek\">δημοσίᾳ</span>), de casa em casa, isto é, privadamente 20:20. No singular <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἶκον</span> (em oposição a <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span>), em diversas casas particulares (Jos., Ant. 4, 74; 163.—Diod S 17, 28, 4 <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἰκίαν</span> <span class=\"greek\">ἀπολαύσαντες</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">βρωτῶν</span>, depois de tomar as refeições em suas respectivas casas) 2:46; 5:42. <span class=\"greek\">ἡ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">οἶκόν</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ἐκκλησία</span>, igreja na casa de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:15</a>; Phlm 2 (ver <span class=\"greek\">ἐκκλησία</span> 3b<span class=\"greek\">α</span>; EJudge, The Social Pattern of Christian Groups in the First Century ’60; LWhite, House Churches: OEANE III 118–21 [bibliografia]). <span class=\"greek\">τὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span>, assuntos domésticos (Lucian, Abdic. 22) 1 Cl 1:3.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Casa de qualquer edifício grande: <span class=\"greek\">οἶκος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βασιλέως</span>, palácio do rei (Ael. Aristid. 32, 12 K.=12 p. 138 D.; 2 Km 11:8; 15:35; 3 Km 7:31; Jos., Ant. 9, 102) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:8</a>. <span class=\"greek\">οἶκος</span> <span class=\"greek\">ἐμπορίου</span> (ver <span class=\"greek\">ἐμπόριον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>b. <span class=\"greek\">οἶκος</span> <span class=\"greek\">προσευχῆς</span>, casa de oração <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:46</a> (os três Is 56:7). <span class=\"greek\">οἶκ</span>. <span class=\"greek\">φυλακῆς</span>, edifício prisional 14:7 (Is 42:7).—Especialmente a casa de Deus (Herodas 1, 26 <span class=\"greek\">οἶκος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θεοῦ</span> [sobre Afrodite]; IKosPH 8, 4 <span class=\"greek\">οἶκος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>.—<span class=\"greek\">οἶκ</span>. em referência a templos já em Eur., Phoen. 1372; Hdt. 8, 143; Pla., Phdr. 24e; inscrições [cf. SIG índice IV <span class=\"greek\">οἶκος</span> d; Thieme 31]; UPZ 79, 4 [II b.c.] <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἄμμωνος</span>; POxy 1380, 3 [II a.d.]; LXX; New Docs 1, 6f; 31; 139): <span class=\"greek\">οἶκος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (Jos., Bell. 4, 281) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:4</a>. Acerca do templo em Jerusalém (3 Km 7:31 <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">κυρίου</span>; Just., D. 86, 6 e outros): <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:46</a> (os três Is 56:7). <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:16</a>a; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:47</a>, 49 (Is 66:1). Especificamente o edifício do templo (Eupolem.: 723 fgm 2, 12 Jac. [em Eus., PE 9, 34, 14]; EpArist 88; 101): <span class=\"greek\">μεταξὺ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυσιαστηρίου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span>, entre o altar e o edifício do templo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.51\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:51</a>. Acerca do santuário celestial, onde Cristo exerce o ofício de sumo sacerdote <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:21</a> (alguns preferem aqui o sentido b<span class=\"greek\">α</span>).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. Em sentido mais amplo, <span class=\"greek\">οἶκ</span>. ocasionalmente equivale a cidade (cf. observação sobre POxy 126, 4.—Jer 22:5; 12:7; TestLevi 10, 5 <span class=\"greek\">οἶκος</span> … <span class=\"greek\">Ἰερους</span>. <span class=\"greek\">κληθήσεται</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:35</a>.</p><p class=\"entry-text\">ⓑ Figuradamente (Philo, Cher. 52 <span class=\"greek\">ὦ</span> <span class=\"greek\">ψυχή</span>, <span class=\"greek\">δέον</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παρθενεύεσθαι</span> e outros).</p><p class=\"entry-text\"><span class=\"greek\">α</span>. Sobre a comunidade cristã como templo espiritual de Deus: <span class=\"greek\">ὡς</span> <span class=\"greek\">λίθοι</span> <span class=\"greek\">ζῶντες</span> <span class=\"greek\">οἰκοδομεῖσθε</span> <span class=\"greek\">οἶκος</span> <span class=\"greek\">πνευματικός</span>, como pedras vivas, deixai-vos edificar numa casa espiritual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:5</a> (ESelwyn, 1 Pt ’46, 286–91; JHElliott [ver bibliografia final] 200–208). A torre, que Hermas emprega como símbolo da comunidade cristã, também é chamada <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>: <span class=\"greek\">ἀποβάλλεσθαι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span>. Hs 9, 13, 9. Em oposição, <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Hs 9, 14, 1.—As passagens seguintes são mais difíceis de classificar; é possível a acepção 2 (os cristãos como família de Deus): <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:17</a>; <span class=\"greek\">ἐν</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἀναστρέφεσθαι</span> <span class=\"greek\">ἥτις</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἐκκλησία</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ζῶντος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:15</a>.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. Morada, habitação, acerca do corpo humano (Just., D. 40, 1 <span class=\"greek\">τὸ</span> <span class=\"greek\">πλάσμα</span> … <span class=\"greek\">οἶκ</span>. <span class=\"greek\">ἐγένετο</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐμφυσήματος</span>; Mel., P. 55, 402 <span class=\"greek\">τοῦ</span> <span class=\"greek\">σαρκίνου</span> <span class=\"greek\">οἴκου</span>; Lucian, Gall. 17), como habitação de espíritos hostis <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:24</a>. Correspondentemente, os gentios são chamados <span class=\"greek\">οἶκ</span>. <span class=\"greek\">δαιμονίων</span> 16:7.</p><p class=\"entry-text\">② Casa, família (Hom. e outros; Artem. 2, 68 p. 161, 11 <span class=\"greek\">μετὰ</span> <span class=\"greek\">ὅλου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span>; Ath. 3, 2 <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑμέτερον</span> <span class=\"greek\">οἶκον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:5</a>; 19:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:2</a>; 11:14; 16:31; 18:8. <span class=\"greek\">ὅλους</span> <span class=\"greek\">οἴκους</span> <span class=\"greek\">ἀνατρέπειν</span>, arruinar famílias inteiras <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:11</a> (cf. Gen 47:12 <span class=\"greek\">πᾶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκος</span> = «toda a família»). <span class=\"greek\">ὁ</span> <span class=\"greek\">Στεφανᾶ</span> <span class=\"greek\">οἶκ</span>., Estéfanas e sua família <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:16</a>; <span class=\"greek\">ὁ</span> <span class=\"greek\">Ὀνησιφόρου</span> <span class=\"greek\">οἶκ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:16</a>; 4:19. <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ταουί</span>̈<span class=\"greek\">ας</span> ISm 13:2. Especialmente frequente em Hermas: <span class=\"greek\">τὰ</span> <span class=\"greek\">ἁμαρτήματα</span> <span class=\"greek\">ὅλου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">σου</span>, os pecados de toda a tua família Hv 1, 1, 9; cf. 1, 3, 1; 2, 3, 1; Hs 7:2. … <span class=\"greek\">σε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">σου</span> v 1, 3, 2; cf. m 2:7; 5, 1, 7; Hs 7:5ff. Com <span class=\"greek\">τέκνα</span> m 12, 3, 6; Hs 5, 3, 9. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:4</a>, 12 (sobre o assunto, Ocellus Luc. 47 <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἰδίους</span> <span class=\"greek\">οἴκους</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τρόπον</span> <span class=\"greek\">οἰκονομήσουσι</span>; Carta 58 de Apolônio de Tiana [Philostrat. I 362, 3]). <span class=\"greek\">ἡ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἐπιτρόπου</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τέκνων</span>, a (viúva) de Epítropo juntamente com toda a sua casa e a de seus filhos IPol 8:2 (Sb 7912 [inscrição de 136 a.d.] <span class=\"greek\">σὺν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">οἴκῳ</span>). <span class=\"greek\">ἀσπάζομαι</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">οἴκους</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδελφῶν</span> <span class=\"greek\">μου</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">γυναιξὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέκνοις</span>, saúdo as famílias dos meus irmãos (na fé), incluindo suas esposas e crianças ISm 13:1. Em passagem que revela influência de Num 12:7, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:2</a>–6 contrasta o <span class=\"greek\">οἶκος</span> de que Moisés era membro e o <span class=\"greek\">οἶκος</span> sobre o qual Cristo preside (cf. SIG 22, 16f <span class=\"greek\">οἶκος</span> <span class=\"greek\">βασιλέως</span>; Thu 1, 129, 3 Xerxes para alguém <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμετέρῳ</span> <span class=\"greek\">οἴκῳ</span>; de modo semelhante <span class=\"greek\">οἶκος</span> de Augusto IGR I, 1109 [4 b.c.], cf. IV, 39b, 26 [27 b.c.]; ver MFlory, TAPA 126, ’96, 292 nota 20). Daí as palavras do versículo 6 <span class=\"greek\">οὗ</span> (isto é, <span class=\"greek\">Χριστοῦ</span>) <span class=\"greek\">οἶκός</span> <span class=\"greek\">ἐσμεν</span> <span class=\"greek\">ἡμεῖς</span>, cuja família somos nós.—Sobre os cristãos como família de Deus, ver também 1b<span class=\"greek\">α</span> acima. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδίου</span> <span class=\"greek\">οἴκ</span>. <span class=\"greek\">προστῆναι</span>, administrar a própria casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:4</a>f; cf. versículo 12 e 5:4.—Sobre a administração de um <span class=\"greek\">οἶκος</span>, ver X., Oeconomicus. Sobre o tema geral da família, MRaepsaet-Charlier, La femme, la famille, la parenté à Rome: L’Antiquité Classique 62, ’93, 247–53.</p><p class=\"entry-text\">③ Clã ou tribo inteira de pessoas descendentes de ancestral comum, casa = descendentes, nação, sentido transferido do de uma única família (Appian, Bell. Civ. 2, 127 §531 <span class=\"greek\">οἴκοι</span> <span class=\"greek\">μεγάλοι</span>, famílias célebres [dos assassinos de César]; Dionys. Byz. 53 p. 23, 1; LXX; Jos., Ant. 2, 202; 8, 111; SibOr 3, 167): <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Δαυίδ</span> (3 Km 12:19; 13:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:27</a>, 69 (sobre a probabilidade de provas epigráficas semíticas da expressão «casa de Davi», ver artigos favoráveis e contrários em Bar 20/2, ’94, 26–39; 20/3, ’94, 30–37; 20/4, ’94, 54f; 20/6, ’94, 47; 21/2, ’95, 78f). <span class=\"greek\">ἐξ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πατριᾶς</span> <span class=\"greek\">Δ</span>. 2:4.—<span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ἰσραήλ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:6</a>; 15:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a>; 7:42 (Am 5:25); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:10</a> (Jer 38:33); 1 Cl 8:3 (citação de origem desconhecida). AcPlCor 2:10. <span class=\"greek\">πᾶς</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ἰσραήλ</span> GJs 7:3 (Jer 9:25). <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ἰς</span>. combinado com <span class=\"greek\">ὁ</span> <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ἰούδα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:8</a> (Jer 38:31). <span class=\"greek\">οἶκ</span>. <span class=\"greek\">Ἰακώβ</span> (Ex 19:3; Is 2:5; Just., A I, 53, 4;, D. 135, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.46\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:46</a>. <span class=\"greek\">οἶκ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἀμαλήκ</span> 12:9.</p><p class=\"entry-text\">④ Casa e o que nela há, propriedade, bens, patrimônio (Hom. e outros; ver também Hdt. 3, 53; Isaeus 7, 42; Pla., Lach. 185a; X., Oec. 1, 5; Demetr.: 722 Fgm. 1, 15 Jac.; Jos., Bell. 6, 282; Just., D. 139, 4): <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">Αἴγυπτον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὅλον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">αὐτοῦ</span>, sobre o Egito e sobre todo o seu patrimônio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:10</a> (cf. Gen 41:40; Artem. 4, 61 <span class=\"greek\">προέστη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">οἴκου</span>).—Ver bibliografia sobre o batismo infantil, por exemplo GDelling, Zur Taufe von ‘Häusern’ im Urchrist., NovT 7, ’65, 285–311=Studien zum NT ’70, 288–310.—JHElliott, A Home for the Homeless ’81. B. 133; 458. Schmidt, Syn. II 508–26. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκουμένη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκουμένη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (particípio presente feminino passivo de <span class=\"greek\">οἰκέω</span>; subentende-se <span class=\"greek\">γῆ</span>. Hdt. e posteriores; empréstimo no rabínico).</p><p class=\"entry-text\">① A terra como região habitada, excluídos os céus acima e as regiões inferiores, a terra habitada, o mundo (Ps 23:1 e frequentemente; Iren., Orig., Hippol., Did., Theoph. Ant.): <span class=\"greek\">πάσας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλείας</span> <span class=\"greek\">τ</span>. <span class=\"greek\">οἰκουμένης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:5</a>. Cf. 21:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:18</a> (Ps 18:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:6</a> (mas ver FSchierse, Verheissung u. Heilsvollendung ’55: «região celestial»). <span class=\"greek\">ὅλη</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>., toda a terra habitada (Diod S 12, 2, 1 <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span>; EpArist 37.—Diod S 3, 64, 6 e Jos., Bell. 7, 43 <span class=\"greek\">πᾶσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:10</a>; 16:14; GJs 4:1. Com <span class=\"greek\">πᾶσα</span> como qualificativo AcPl Ha 9, 5. <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἄνθρωποι</span> PtK 15:20. <span class=\"greek\">αἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἐκκλησίαι</span>, as congregações por todo o mundo MPol 5:1; cf. 8:1; 19:2.</p><p class=\"entry-text\">② O mundo como unidade administrativa, o Império Romano (na linguagem hiperbólica comumente usada em referência aos imperadores, o Império Romano equivalia ao mundo inteiro [como, por exemplo, o império de Xerxes: Ael. Aristid. 54 p. 675 D., e o de Ciro: Jos., Ant. 11, 3]: OGI 666, 4; 668, 5 <span class=\"greek\">τῷ</span> <span class=\"greek\">σωτῆρι</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εὐεργέτῃ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκουμένης</span> [Nero]; 669, 10; SIG 906 A, 3f <span class=\"greek\">τὸν</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">οἰκουμένης</span> <span class=\"greek\">δεσπότην</span> [Juliano]; cf. Artapanus: 726 Fgm. 3, 22 Jac., em Eus., PE 9, 27, 22: Deus como <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">δεσπότης</span>; POxy 1021, 5ff; Sb 176, 2.—Cf. 1 Esdr 2:2; Philo, Leg. ad Gai. 16; Jos., Bell. 4, 656, Ant. 19, 193; Just., A I, 27, 2; Ath. 1, 1).</p><p class=\"entry-text\">ⓐ Como tal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:5</a> (como em Jos., Ant. 12, 48 <span class=\"greek\">πᾶσι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span> <span class=\"greek\">Ἰουδαίοις</span>, exceto que <span class=\"greek\">οἰκ</span>. aqui é empregado no sentido de 1 acima, como área geográfica. Cf. PLond VI, 1912, 100).</p><p class=\"entry-text\">ⓑ Seus habitantes 17:6.—GAalders, Het Romeinsche Imperium en het NT ’38.</p><p class=\"entry-text\">③ Todos os habitantes da terra, extensão figurada de 1 (cf. <span class=\"greek\">γῆ</span>): mundo, humanidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a> (cf. Ps 9:9; Artapanus: 726 Fgm. 3:22 Jac., Deus como <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">δεσπότης</span>); 19:27. Acerca de Satanás: <span class=\"greek\">ὁ</span> <span class=\"greek\">πλανῶν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ὅλην</span>, aquele que engana toda a humanidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:9</a>. A passagem <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">δόγμα</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">Καίσαρος</span> <span class=\"greek\">Αὐγούστου</span> <span class=\"greek\">ἀπογράφεσθαι</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span> (cf. <span class=\"greek\">κόσμον</span> … <span class=\"greek\">πάντα</span> LBW II, 1192, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:1</a> também pertence aqui. Para o evangelista, é de grande importância que o nascimento do Salvador do mundo coincida com outro acontecimento que igualmente afetava todas as pessoas no «mundo». Mas também se pode dizer que Augusto governava a <span class=\"greek\">οἰκ</span>., porque a palavra também é usada no sentido de 2 acima. Sobre a vinculação do nascimento de um governante ao destino da humanidade, ver IPriene 105, 4–11 acerca da importância do nascimento de César Augusto.</p><p class=\"entry-text\">④ Emprego extraordinário: <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἔκτισας</span> 1 Cl 60:1, onde <span class=\"greek\">οἰκ</span>. parece designar o mundo inteiro (na medida em que os seres vivos o habitam, portanto também o domínio de seres transcendentes). Ver Johnston s.v. <span class=\"greek\">κόσμος</span>.—Também <span class=\"greek\">ἡ</span> <span class=\"greek\">οἰκ</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">μέλλουσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:5</a> = <span class=\"greek\">ὁ</span> <span class=\"greek\">μέλλων</span> <span class=\"greek\">αἰών</span> (6:5); JMeier, Biblica 66, ’85, 504–33; ver <span class=\"greek\">αἰών</span> 2b.—JKaerst, Die antike Idee der Oekumene 1903; JVogt, Orbis terrarum 1929; MPaeslack, Theologia Viatorum II, ’50, 33–47.—GHusson, <span class=\"greek\">ΟΙΚΙΑ</span>: Le vocabulaire de la maison privée en Égypte d’après les papyrus Grecs ’83; Pauly-W. XVII 2123–74; Kl. Pauly IV 254–56; B. 13.—DELG s.v. <span class=\"greek\">οἶκο</span> C. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκουργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκουργέω</span> (<span class=\"greek\">οἰκουργός</span>), cumprir responsabilidades numa casa, dedicar-se às tarefas domésticas, cuidar das coisas da casa: <span class=\"greek\">τὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">οἰκ</span>., cumprir as próprias obrigações domésticas 1 Cl 1:3 (autores trágicos e outros empregam o verbo <span class=\"greek\">οἰκουρεῖν</span>, que o manuscrito de Jerusalém restaura por raspagem no texto de Clemente). Não deve ser equiparado a <span class=\"greek\">οἰκοδεσποτέω</span>, «administrar a casa», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:14</a> (ver a distinção entre <span class=\"greek\">οἰκουρός</span> e <span class=\"greek\">οἰκονόμος</span> em Cass. Dio 56, 3 [ver o próximo verbete]). Tanto no ideal semítico quanto no helênico, esperava-se que as mulheres permanecessem em casa e cumprissem os deveres domésticos. Ao papel de uma mulher respeitável correspondia observar <span class=\"greek\">οἰκουρίαν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">σέμνον</span> <span class=\"greek\">βίον</span>, «cuidar das coisas de casa e levar vida recatada», Alciphron 3, 22 [58]; no AT, contraste-se a mulher «virtuosa» ocupada em casa em Pr 31 com a mulher «dissoluta» que não permanece em casa em 7:11.—Ver DELG s.v. <span class=\"greek\">ἔργον</span> I 2 p. 364. M-M. s.v.-<span class=\"greek\">ός</span>; Field, Notes, 220–21.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκουργός, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκουργός</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">ἔργον</span>; em lugar de <span class=\"greek\">οἰκουρός</span> em Aristoph. e outros; a forma com <span class=\"greek\">γ</span> ocorre em outro lugar somente em Soranus p. 18, 2 v.l. [em lugar de <span class=\"greek\">οἰκουρός</span>]: <span class=\"greek\">οἰκουργὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">καθέδριον</span> <span class=\"greek\">διάγειν</span> <span class=\"greek\">βίον</span>), relativo ao cumprimento das responsabilidades domésticas, ocupado em casa, cumpridor dos deveres domésticos, acerca de mulheres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:5</a> (cf. Philo, Exsecr. 139 <span class=\"greek\">σώφρονας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">οἰκουροὺς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">φιλάνδρους</span>; Cass. Dio 56, 3). Ver verbete precedente; também Field, Notes, 220–22 e o verbete seguinte.—Ver DELG s.v. <span class=\"greek\">ἔργον</span> I 2 p. 364. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκουρός, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκουρός</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">οὖρος</span>, «vigilante, guardião»; Aeschyl. e outros; PGM 11a, 11; Philo, Rer. Div. Her. 186), que permanece em casa, doméstico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:5</a> t.r. (ver <span class=\"greek\">οἰκουργέω</span> e <span class=\"greek\">οἰκουργός</span> quanto à bibliografia).—DELG s.v. <span class=\"greek\">ὁράω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0251-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">οἰκοφθόρος, ον</h1><div class=\"entry-meta\"><span>adjetivo; substantivado</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">οἰκοφθόρος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">οἶκος</span>, <span class=\"greek\">φθείρω</span>; Eur., Pla.; Philo, Agr. 73; SibOr 2, 257; Suda s.v. <span class=\"greek\">Ἰλάριος</span> aplica <span class=\"greek\">οἰκ</span>. a ato de adultério que destrói uma família; cf. Plut., Mor. 12b <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">οἰκοφθορίαι</span> <span class=\"greek\">γαμετῶν</span>, «sedutores de mulheres casadas»), relativo a ser causa de corrupção numa casa, destruidor de casas ou famílias, como substantivo IEph 16:1. O destino dos sedutores (Hesych. completa a equivalência <span class=\"greek\">οἰκοφθόρος</span> = <span class=\"greek\">μοιχός</span>) funciona como premissa de argumento do menor para o maior: «O argumento é que, se tais adúlteros pereceram, quanto mais aqueles que corrompem a fé por seu mau ensinamento». WSchoedel, Ignatius of Antioch ’85, 79.—WBauer concluiu que o termo era empregado especificamente (citando a conexão com a imagem de IEph 15:3; ver <span class=\"greek\">οἶκος</span> 1a<span class=\"greek\">β</span>) no sentido de destruidor do templo, argumentando que, visto que Inácio é «claramente dependente» de 1 Cor 6 (versículo 19; cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:16</a>f) neste ponto, provavelmente pensava na introdução da imoralidade como meio específico de destruição; em apoio Bauer compara Plut., Mor. (ver acima) e PGrenf I, 53, 19f.—DELG s.v. <span class=\"greek\">φθείρω</span>.</p></section></article>\n"};
